SELECT COUNT(*) FROM singer;
SELECT COUNT(*) AS total_singers FROM singer;
SELECT singer.Name, singer.Country, singer.Age FROM singer INNER JOIN concert ON singer.Singer_ID = singer_in_concert.Singer_ID INNER JOIN stadium ON singer_in_concert.Stadium_ID = stadium.Stadium_ID ORDER BY singer.Age DESC, singer.Country;
SELECT Name, Country, Age FROM singer ORDER BY Age DESC;
SELECT AVG(singer.id), MIN(singer.id), MAX(singer.id) FROM singer;
SELECT AVG(Singer_ID), MIN(Singer_ID), MAX(Singer_ID) FROM singer;
SELECT singer.Name, singer.release_year FROM singer INNER JOIN singer_in_concert ON singer.Singer_ID = singer_in_concert.Singer_ID INNER JOIN concert ON singer_in_concert.concert_ID = concert.concert_ID WHERE singer.release_year = (SELECT MIN(singer.release_year) FROM singer)
SELECT DISTINCT s.Name, c.Year AS release_year FROM singer s JOIN concert c ON s.Singer_ID = c.Singer_ID JOIN singer_in_concert sc ON c.concert_ID = sc.concert_ID WHERE c.Year = (SELECT MIN(c.Year) FROM concert c)
