SELECT DISTINCT Country FROM singer WHERE Birthday = '2001'
SELECT singer.Country, COUNT(singer.Country) AS singer_count FROM singer JOIN singer_in_concert ON singer.Singer_ID = singer_in_concert.Singer_ID JOIN concert ON singer_in_concert.concert_ID = concert.concert_ID GROUP BY singer.Country;
SELECT singer.Country, COUNT(singer.Country) AS count_per_country FROM singer JOIN singer_in_concert ON singer.Singer_ID = singer_in_concert.Singer_ID JOIN concert ON singer_in_concert.concert_ID = concert.concert_ID GROUP BY singer.Country, singer_in_concert.concert_ID;
SELECT singer.Name, singer.Song_Name FROM singer INNER JOIN singer_in_concert ON singer.Singer_ID = singer_in_concert.Singer_ID INNER JOIN concert ON singer_in_concert.concert_ID = concert.concert_ID WHERE singer.Instrumental_Age > (SELECT AVG(Birthday) FROM singer)
SELECT s.Name, c.Concert_Name FROM singer s JOIN concert c ON s.Singer_ID = c.Singer_ID JOIN stadium st ON c.Stadium_ID = st.Stadium_ID WHERE s.Birthday IS NOT NULL AND s.Birthdate > (SELECT AVG(Birthdate) FROM singer) ORDER BY s.Name
SELECT stadium.Location, stadium.Name FROM stadium WHERE stadium.Capacity BETWEEN 5000 AND 10000;
