SELECT s.Name, c.Highest FROM singer s JOIN concert c ON s.Singer_ID = c.Singer_ID JOIN singer_in_concert sic ON c.concert_ID = sic.concert_ID WHERE c.Year > 2013 AND sic.Stadium_ID = s.Stadium_ID GROUP BY s.Name, c.Highest
