SELECT AVG(stadium.Average) AS average_attendance FROM stadium WHERE stadium.Stadium_ID NOT IN (SELECT concert.Stadium_ID FROM concert INNER JOIN singer_in_concert ON concert.concert_ID = singer_in_concert.concert_ID WHERE singer_in_concert.Singer_ID IN (SELECT Singer_ID FROM singer WHERE singer.Song_release_year = 2014))
SELECT DISTINCT s.Lowest AS Lowest_Attendance FROM stadium s JOIN singer_in_concert c ON s.Stadium_ID = c.Stadium_ID JOIN concert ON c.concert_ID = concert.concert_ID WHERE concert.Year = '2014' AND s.Lowest IS NOT NULL;
SELECT singer.Name, concert.Theme, singer_in_concert.Singer_ID AS Number_of_Singers FROM concert JOIN singer ON concert.Stadium_ID = stadium.Stadium_ID JOIN singer_in_concert ON singer_in_concert.concert_ID = concert.concert_ID;
