SELECT Documents.Document_Name, Templates.Template_Type_Code, Templates.Template_Details, Paragraphs.Paragraph_Text FROM Templates JOIN Documents ON Templates.Template_ID = Documents.Template_ID JOIN Paragraphs ON Documents.Document_ID = Paragraphs.Document_ID WHERE Templates.Template_Type_Description LIKE '%w%'
SELECT D.Document_Name, D.Template_ID, D.Template_Details, D.Date_Effective_To, D.Date_Effective_From, D.Other_Details, P.Paragraph_Text FROM Documents D JOIN Paragraphs P ON D.Document_ID = P.Document_ID WHERE D.Document_Description LIKE '%w%'
