SELECT p.first_name, p.last_name, m.year FROM players p JOIN matches m ON p.player_id = m.loser_id WHERE m.year IN (2013, 2016) AND p.hand = m.loser_hand;
SELECT p.first_name, p.last_name, p.hand, p.birth_date, p.country_code FROM players p JOIN matches m ON p.player_id = m.loser_id JOIN rankings r ON m.match_num = r.ranking_date WHERE m.year IN ('2013', '2016') AND p.hand = p.hand AND p.first_name != p.last_name AND p.country_code = p.country_code DISTINCT p.first_name, p.last_name
