SELECT players.country_code, players.first_name FROM players JOIN matches ON players.player_id = matches.winner_id JOIN rankings ON players.player_id = rankings.player_id WHERE matches.tourney_id = (SELECT tourney_id FROM matches WHERE tourney_name = 'WTA Championships') AND matches.tourney_id = (SELECT tourney_id FROM matches WHERE tourney_name = 'Australian Open')
SELECT p.first_name, p.country_code FROM players p JOIN matches m ON p.player_id = m.winner_id JOIN rankings r ON p.player_id = r.player_id WHERE m.tourney_name = 'WTA Championships' AND m.tourney_name = 'Australian Open' AND r.ranking_points IS NOT NULL;
SELECT p.first_name, p.country_code FROM players p JOIN rankings r ON p.player_id = r.player_id ORDER BY p.rankings.points DESC LIMIT 1;
SELECT p.first_name, p.country_code FROM players p JOIN rankings r ON p.player_id = r.player_id ORDER BY p.birth_date DESC LIMIT 1;
SELECT p.first_name, p.last_name, p.birth_date FROM players p JOIN rankings r ON p.player_id = r.player_id ORDER BY birth_date ASC;
SELECT first_name, last_name FROM players ORDER BY first_name, last_name;
SELECT p.first_name, p.last_name, p.hand, p.birth_date FROM players p WHERE p.hand = 'left' ORDER BY p.birth_date DESC LIMIT 100;
SELECT p.first_name, p.last_name, p.birth_date, p.hand, p.country_code FROM players p JOIN rankings r ON p.player_id = r.player_id ORDER BY p.birth_date ASC;
SELECT p.first_name, p.country_code FROM players p JOIN matches m ON p.player_id = m.loser_id JOIN rankings r ON m.match_num = r.match_num WHERE r.ranking_points = (SELECT MAX(ranking_points) FROM rankings r2) ORDER BY p.country_code ASC LIMIT 1;
SELECT p.first_name, p.country_code, p.player_id FROM players p JOIN matches m ON p.player_id = m.loser_id JOIN rankings r ON p.player_id = r.player_id WHERE m.tourney_id = (SELECT MAX(tourney_id) FROM matches) ORDER BY p.country_code DESC LIMIT 1;
SELECT year, COUNT(*) AS match_count FROM matches GROUP BY year ORDER BY match_count DESC LIMIT 1;
SELECT year, COUNT(*) as match_count FROM matches GROUP BY year ORDER BY match_count DESC LIMIT 1;
SELECT p.first_name, p.rankings.ranking_points AS rank_points FROM players p JOIN rankings r ON p.player_id = r.player_id ORDER BY r.rankings.ranking_points DESC LIMIT 1;
SELECT p.first_name, p.last_name, m.rank_points, m.match_num FROM players p JOIN matches m ON p.player_id = m.loser_id WHERE m.rank_points = (SELECT MAX(rank_points) FROM matches) ORDER BY p.rank_points DESC;
SELECT p.first_name, p.last_name, p.country_code, r.ranking, r.ranking_points FROM players p JOIN rankings r ON p.player_id = r.player_id WHERE r.ranking_points = (SELECT MAX(ranking_points) FROM rankings) AND p.country_code = 'AU' AND p.hand = 'H' AND p.country_code = 'A' AND p.winner_id = r.player_id;
SELECT p.first_name, p.last_name, m.winner_name, m.loser_name, m.winner_rank_points, m.loser_rank_points FROM players p JOIN matches m ON p.player_id = m.loser_id WHERE m.tourney_name = 'Australian Open' AND m.winner_rank_points > m.loser_rank_points ORDER BY m.winner_rank_points DESC
SELECT p.first_name, p.last_name, m.minutes, m.round FROM players p JOIN matches m ON p.player_id = m.loser_id ORDER BY m.minutes DESC;
SELECT p.first_name, p.last_name, m.loser_name, m.best_of FROM players p JOIN matches m ON p.player_id = m.loser_id WHERE m.best_of = (SELECT MAX(best_of) FROM matches) ORDER BY p.first_name, p.last_name;
SELECT players.first_name, AVG(ranking_points) AS average_ranking FROM players JOIN rankings ON players.player_id = rankings.player_id GROUP BY players.first_name
SELECT p.first_name, AVG(r.ranking_points) AS average_rankings FROM players p JOIN rankings r ON p.player_id = r.player_id ORDER BY p.first_name
SELECT players.first_name, players.last_name, SUM(rankings.rank_points) AS total_ranking_points FROM players JOIN rankings ON players.player_id = rankings.player_id GROUP BY players.first_name, players.last_name
