SELECT Professionals.professional_id, Owners.street, Owners.home_phone, Professionals.email_address, Professionals.cell_number FROM Professionals INNER JOIN Owners ON Professionals.professional_id = Owners.owner_id;
SELECT p.professional_id, p.first_name, p.last_name, t.treatment_type_description, t.date_of_treatment, t.cost_of_treatment FROM Professionals p JOIN Treatments t ON p.professional_id = t.professional_id JOIN Dogs d ON t.dog_id = d.dog_id WHERE t.treatment_type_code = (SELECT treatment_type_code FROM Treatment_Types WHERE treatment_type_description = '2 or more treatments') ORDER BY p.professional_id;
SELECT breed_name FROM Breeds ORDER BY breed_code ASC LIMIT 1;
SELECT breed_name FROM Breeds WHERE breed_code IN (SELECT Dogs.breed_code FROM Dogs JOIN Treatment_Types ON Dogs.breed_code = Treatment_Types.treatment_type_code WHERE Treatment_Types.treatment_type_code = 1 AND Treatments.dog_id = (SELECT Dogs.dog_id FROM Dogs WHERE Dogs.abandoned_yn = 'Y') AND Dogs.abandoned_yn = 'Y')
SELECT o.owner_id, o.last_name, t.cost_of_treatment FROM Owners o JOIN Treatments t ON o.owner_id = t.dog_id ORDER BY t.cost_of_treatment DESC;
SELECT Dogs.owner_id, Dogs.dog_id, Professionals.last_name, Treatments.cost_of_treatment FROM Dogs JOIN Professionals ON Dogs.owner_id = Professionals.owner_id JOIN Treatments ON Treatments.dog_id = Dogs.dog_id JOIN Treatment_Types ON Treatments.treatment_type_code = Treatment_Types.treatment_type_code ORDER BY Treatments.cost_of_treatment DESC;
