SELECT Dogs.owner_id, Dogs.zip_code FROM Dogs JOIN Owners ON Dogs.owner_id = Owners.owner_id JOIN Charges ON Dogs.dog_id = Charges.charge_id JOIN Sizes ON Dogs.size_code = Sizes.size_code JOIN Treatments ON Dogs.dog_id = Treatments.dog_id JOIN Treatment_Types ON Treatments.treatment_type_code = Treatment_Types.treatment_type_code JOIN Professionals ON Treatments.professional_id = Professionals.professional_id;
